-- Additive source metadata. Existing documents, users and moderation data are untouched.
alter table public.country_documents
 add column if not exists visa_type text,
 add column if not exists sort_order integer,
 add column if not exists requirement text not null default 'required' check(requirement in ('required','conditional','recommended')),
 add column if not exists source_name text,
 add column if not exists source_document text,
 add column if not exists source_type text,
 add column if not exists source_scope text,
 add column if not exists source_updated_at date,
 add column if not exists editor_note text,
 add column if not exists details jsonb not null default '[]'::jsonb;
create index if not exists country_documents_order_idx on public.country_documents(country_id,visa_type,sort_order);
-- Source publication/update dates are unknown and deliberately NULL.
insert into public.country_documents (id,country_id,title,body,category,source_url,visa_type,sort_order,requirement,source_name,source_document,source_type,source_scope,source_updated_at,editor_note,details)
select id,country_id,title,body,category,source_url,visa_type,sort_order,requirement,source_name,source_document,source_type,source_scope,source_updated_at,editor_note,details from jsonb_to_recordset($spain$[{"id": "1de9d862-d2e3-5be5-b46a-9ebb4c15f00a", "country_id": "spain", "title": "Pasaport", "body": "Planlanan seyahatin dönüş tarihinden itibaren en az 3 ay daha geçerli olmalı; en az 2 karşılıklı boş sayfası bulunmalıdır. Evlilik nedeniyle soyadı değişmişse pasaportta evlilik sonrası güncel soyadı bulunmalıdır.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 1, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": []}, {"id": "eaf68fb1-bce4-55b8-96fb-a7f152ecee84", "country_id": "spain", "title": "Biyometrik fotoğraf", "body": "2 adet fotoğraf istenir; biri Schengen başvuru formuna yapıştırılır. Son 6 ay içinde çekilmiş, 35 × 45 mm ölçülerinde ve gözlük gibi aksesuarlar olmadan hazırlanmalıdır. Ölçülere uymayan fotoğraflar kabul edilmez. Kaynak, ihtiyaç halinde başvuru merkezinde fotoğraf hizmeti satın alınabileceğini belirtir; ücret bilgisi vermez.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 2, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": []}, {"id": "76453d6e-cb0d-577c-b5d1-e48f660e3524", "country_id": "spain", "title": "Ulaşım rezervasyonları", "body": "Uçak rezervasyonu, başvuru gününden en az 15 gün sonraki seyahat için düzenlenmelidir. Ara geçişler varsa uçak, tren vb. rezervasyonlar da sunulmalıdır. Birden fazla Schengen ülkesi ziyaret ediliyorsa en uzun kalış İspanya’da olmalıdır; eşit süreli kalışlar varsa ilk giriş İspanya olmalıdır.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 3, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": []}, {"id": "cfa76a69-c1f6-5a44-b6c5-cb13a910bfc6", "country_id": "spain", "title": "Konaklama belgeleri", "body": "Otel rezervasyonu seyahatin tamamını kapsamalı, eksik gün olmamalıdır. Kendi evinde kalacak kişi tapu sunmalıdır. Başkasının evinde kalınacaksa ev sahibinin İspanya polisinden aldığı sarı davetiye ya da kira sözleşmesi istenir. Kaynak Airbnb için de kira sözleşmesinden (AirB&B sözleşmesi) bahseder.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 4, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": []}, {"id": "76da0ec2-95c4-52ef-9df2-074e0a6f5244", "country_id": "spain", "title": "Yurtdışı seyahat sağlık sigortası", "body": "Sigorta seyahatten 1 gün önce başlayacak şekilde düzenlenmeli, seyahatin tamamını kapsamalı, en az 30.000 € teminatlı ve Schengen Bölgesi’nde geçerli olmalıdır. 7 günden kısa seyahatler için en az 7 günlük sigorta sunulmalıdır. Kaynak PDF sigortanın ıslak imzalı veya kaşeli olmasını şart koşmaz.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 5, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": []}, {"id": "b71a51a7-a5ca-5f76-900c-9fc33ce93c66", "country_id": "spain", "title": "Seyahat amacı / niyet dilekçesi", "body": "Seyahat nedenini açıklayan İspanyolca niyet dilekçesi sunulmalıdır.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 6, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": []}, {"id": "9f567d1f-c738-501a-bcd4-0a3ca62c9772", "country_id": "spain", "title": "Çalışma veya gelir durumunu açıklayan belgeler", "body": "Durumuna uygun alt listeyi incele. Ana evrak sırası değişmez; bu seçim belge muafiyeti veya uygunluk kararı değildir.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 7, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": [{"title": "A. Çalışanlar", "applies_to": ["employee"], "items": ["İşverenin yazdığı, imzaladığı ve kaşelediği; seyahat tarihlerini açıkça belirten İspanyolca işveren mektubu.", "e-Devlet’ten alınmış QR kodlu işe giriş bildirgesi.", "e-Devlet’ten alınmış QR kodlu SGK hizmet dökümü.", "Son 3 aya ait, işyerinin imzaladığı ve kaşelediği maaş bordrosu.", "İşyerinin faaliyet belgesi.", "İşyerinin Resmî Gazete kaydı ve imza sirküleri.", "Vergi levhası."]}, {"title": "B. İşveren / şirket sahipleri", "applies_to": ["owner"], "items": ["Şirket ortaklığı varsa şirket ortağının yazdığı, imzaladığı ve kaşelediği; seyahat tarihlerini ve ortaklık durumunu gösteren İspanyolca dilekçe. Şirketin %100 sahibi veya tüzel kişi olunması durumunda kişinin kendisinin yazdığı, imzaladığı ve kaşelediği; seyahat tarihlerini ve şirket sahipliğini gösteren İspanyolca dilekçe.", "e-Devlet’ten alınmış QR kodlu SGK hizmet dökümü.", "Son 3 aya ait, işyerinin imzaladığı ve kaşelediği maaş bordrosu.", "İşyerinin faaliyet belgesi.", "İşyerinin Resmî Gazete kaydı ve imza sirküleri.", "Vergi levhası."]}, {"title": "C. Emekliler", "applies_to": ["retired"], "items": ["e-Devlet’ten alınmış QR kodlu emeklilik belgesi."]}, {"title": "D. Çalışmayanlar ve öğrenciler", "applies_to": ["unemployed", "student"], "items": ["Sponsor sunulması zorunludur; kaynağa göre sponsor yalnız anne, baba veya eş olabilir.", "Sponsor, masrafları karşılamayı kabul ettiğini beyan eden dilekçe ve çalışma durumuna uygun yukarıdaki destekleyici evrakları sunmalıdır.", "Başvuru sahibinin e-Devlet’ten alınmış QR kodlu SGK hizmet dökümü sunulmalıdır.", "Başvuru sahibi öğrenciyse ayrıca öğrenci belgesi sunulmalıdır."]}]}, {"id": "7a3828b6-2236-55a7-9f1e-8b829cd0eaf7", "country_id": "spain", "title": "Maddi durumu gösteren belgeler", "body": "TL, Euro veya Dolar cinsinden vadesiz banka hesabına ait son 6 aylık hesap hareketleri sunulmalıdır. Hesap hareketleri başvuru gününden en geç 1 hafta önce alınmış olmalıdır. Kaynak, ulaşım ve konaklama masraflarına ek olarak günlük 150 € hesaplanmasını ister: 7 gün × 150 € = 1.050 € + uçak + otel. Altın, vadeli mevduat ve fon hesaplarının dikkate alınmadığı belirtilir.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 8, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": [{"title": "Zorunlu hesap dökümü", "applies_to": [], "items": ["Kaynağa göre banka imza sirküleri sunmaya gerek yoktur."]}, {"title": "Tavsiye ve ek belgeler", "applies_to": [], "requirement": "recommended", "items": ["Kaynak bankada en az 1.500–2.000 € gösterilmesini tavsiye eder; bu tutar herkes için kesin bir asgari zorunluluk değildir.", "QR kodlu vadesiz banka hesap özeti sunulması tavsiye edilir.", "Ek olarak tapu ve araç ruhsatı sunulabilir."]}]}, {"id": "bbd567d1-7364-5af6-94ed-517a16f5891c", "country_id": "spain", "title": "Vukuatlı nüfus kayıt örneği", "body": "e-Devlet üzerinden “Nüfus / Aile” seçeneğiyle alınmış vukuatlı nüfus kayıt örneği.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 9, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": []}, {"id": "e0d07f2a-f7ea-5898-a05b-94d8800daa54", "country_id": "spain", "title": "Tarihçeli yerleşim yeri belgesi", "body": "e-Devlet üzerinden alınmış tarihçeli yerleşim yeri belgesi. Kaynak bu belgeyi ikametgâh belgesinden ayrı bir madde olarak ister.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 10, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": []}, {"id": "6c5f6618-0502-5f96-b953-c76f0439a80f", "country_id": "spain", "title": "İkametgâh belgesi", "body": "e-Devlet üzerinden alınmış ikametgâh (yerleşim yeri) belgesi. 10. maddeyle birleştirilmez; kaynakta ayrı istenir.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 11, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": []}, {"id": "9c339ae7-4834-583c-9797-454ba6b6f776", "country_id": "spain", "title": "18 yaş altı başvuruları", "body": "Bu madde yalnız 18 yaşından küçük başvuru sahiplerine uygulanır. Özel koşulları aşağıdan kontrol et.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 12, "requirement": "conditional", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": [{"title": "Doğum kaydı ve dil", "applies_to": [], "items": ["e-Devlet’ten alınmış Formül A veya doğum belgesi sunulur. e-Devlet’ten İspanyolca dahil çok dilli alınabilir; başka dildeyse yeminli tercümanın İspanyolca çevirisi gerekir."]}, {"title": "Muvafakatname, tercüme ve apostil", "applies_to": [], "items": ["Çocuk anne ve babasıyla birlikte seyahat etmiyorsa birlikte gideceği kişiye yönelik noter muvafakatnamesi gerekir. Anne ve baba noter huzurunda çocuğun “İspanya ülkesine, … ile birlikte gitmesine” ifadesinin kesinlikle geçtiği beyanı vermelidir.", "Muvafakatnamenin yeminli tercüman tarafından İspanyolcaya çevrilmiş ve apostil edilmiş Türkçe ve İspanyolca orijinalleri ile “ASLI GİBİDİR” kopyaları sunulmalıdır."]}, {"title": "Tek ebeveyn, vefat ve mahkeme kararı", "applies_to": [], "items": ["Çocuk yalnız annesiyle gidiyorsa baba anneye; yalnız babasıyla gidiyorsa anne babaya muvafakat vermelidir.", "Anne veya babadan biri vefat etmişse e-Devlet’ten alınmış çok dilli Formül C belgesi sunulur.", "Kaynak, yasal ebeveynlerin mahkeme kararıyla değiştiği durum için mahkeme kararının yeminli tercüman tarafından İspanyolca çevirisini, orijinalini ve “ASLI GİBİDİR” kopyasını ister. Duruma özel uygulamayı başvuru merkezinden teyit et."]}]}, {"id": "0da4d6a5-34f1-5b1d-a199-5e5a9feb0698", "country_id": "spain", "title": "Pasaport ve kimlik fotokopileri", "body": "Kimlik ve pasaport fotokopileri; mevcut pasaportun ön yüzü, Schengen vizeleri ve damgalı sayfaları sunulmalıdır. Varsa önceki pasaportlardaki Schengen vizeleri ve giriş-çıkış damgaları da eklenmelidir.", "category": "Turistik vize", "source_url": null, "visa_type": "tourism_c", "sort_order": 13, "requirement": "required", "source_name": "BLS International Spain Visa Application Center in İstanbul", "source_document": "C Tipi Turistik Vize Başvurusu Gerekli Evrak Listesi ve Evrak Sıralaması", "source_type": "application_center", "source_scope": "İstanbul başvuru merkezi için yayımlanmış C tipi turistik vize evrak listesi.", "source_updated_at": null, "editor_note": null, "details": []}]$spain$::jsonb) as d(id uuid,country_id text,title text,body text,category text,source_url text,visa_type text,sort_order integer,requirement text,source_name text,source_document text,source_type text,source_scope text,source_updated_at date,editor_note text,details jsonb)
on conflict(id) do nothing;
-- Preserve every existing record. Only valid completed application dates enter aggregate stats.
create or replace function public.country_stats(target_country text) returns table(experiences bigint,questions bigint,tips bigint,average_days numeric,recent bigint) language sql stable security invoker set search_path='' as $$
 select count(*) filter(where kind='experience'),count(*) filter(where kind='question'),count(*) filter(where kind='tip'),round(avg(decision_date-application_date) filter(where kind='experience' and application_date>='1985-01-01'::date and decision_date>=application_date and decision_date<=current_date)),count(*) filter(where created_at>now()-interval '7 days') from public.posts where country_id=target_country and status='approved'
$$;

-- Comments publish immediately; posts retain their existing approval workflow.
alter table public.comments alter column status set default 'approved';
drop policy if exists comments_insert on public.comments;
create policy comments_insert on public.comments for insert to authenticated with check(user_id=auth.uid() and status='approved' and approved_by is null and exists(select 1 from public.posts p where p.id=post_id and p.status='approved'));
create or replace function public.publish_new_comment() returns trigger language plpgsql security definer set search_path='' as $$ begin
 if not exists(select 1 from public.posts where id=new.post_id and status='approved') then raise exception 'Published post required';end if;
 new.status:='approved';new.approved_at:=now();new.approved_by:=null;return new;
end $$;
revoke execute on function public.publish_new_comment() from public,anon,authenticated;
drop trigger if exists publish_new_comment on public.comments;
create trigger publish_new_comment before insert on public.comments for each row execute function public.publish_new_comment();
create or replace function public.reward_published_comment(target uuid) returns void language plpgsql security definer set search_path='' as $$ declare c public.comments%rowtype;changed integer;b record;total integer;begin
 select * into c from public.comments where id=target and status='approved';if not found then return;end if;
 insert into public.reputation_events(user_id,reference,points) values(c.user_id,'comment_approval:'||c.id::text,2) on conflict(reference) do nothing;get diagnostics changed=row_count;
 if changed=0 then return;end if;
 update public.profiles set reputation=reputation+2 where id=c.user_id;
 select count(*) into total from public.comments where user_id=c.user_id and status='approved';
 for b in select * from public.badges where kind='comment' and coalesce(to_jsonb(badges)->>'badge_group','legacy')='legacy' and threshold<=total loop
  insert into public.user_badges(user_id,badge_id) values(c.user_id,b.id) on conflict do nothing;
 end loop;
 insert into public.notifications(user_id,post_id,message)
 select recipient,c.post_id,'Gönderine veya yorumuna yeni bir yanıt geldi.' from (
 select user_id recipient from public.posts where id=c.post_id union select user_id from public.comments where id=c.parent_comment_id
 ) people where recipient<>c.user_id and coalesce((select replies from public.notification_preferences where user_id=recipient),true);
end $$;
revoke execute on function public.reward_published_comment(uuid) from public,anon,authenticated;
create or replace function public.comment_published_rewards() returns trigger language plpgsql security definer set search_path='' as $$ begin perform public.reward_published_comment(new.id);return null;end $$;
revoke execute on function public.comment_published_rewards() from public,anon,authenticated;
drop trigger if exists comment_published_rewards on public.comments;
create trigger comment_published_rewards after insert on public.comments for each row execute function public.comment_published_rewards();
-- Release only the existing pending queue on published posts. Removed comments stay removed.
do $$ declare c record;begin
 for c in update public.comments set status='approved',approved_by=null,approved_at=now() where status='pending' and exists(select 1 from public.posts p where p.id=post_id and p.status='approved') returning id loop
 perform public.reward_published_comment(c.id);
 end loop;
end $$;

-- Official-source catalog. Additive and repeatable; existing administrator edits are preserved.
-- Run after migration 002; publication dates are not inferred from retrieval dates.
alter table public.countries add column if not exists is_schengen boolean not null default false;
alter table public.country_documents add column if not exists source_checked_at date;
alter table public.country_documents add column if not exists topic_ids text[] not null default '{}';
insert into public.countries(id,name,code,flag,is_schengen)
select * from jsonb_to_recordset($countries$[{"id": "germany", "name": "Almanya", "code": "DE", "flag": "🇩🇪", "is_schengen": true}, {"id": "estonia", "name": "Estonya", "code": "EE", "flag": "🇪🇪", "is_schengen": true}, {"id": "poland", "name": "Polonya", "code": "PL", "flag": "🇵🇱", "is_schengen": true}, {"id": "france", "name": "Fransa", "code": "FR", "flag": "🇫🇷", "is_schengen": true}, {"id": "italy", "name": "İtalya", "code": "IT", "flag": "🇮🇹", "is_schengen": true}, {"id": "greece", "name": "Yunanistan", "code": "GR", "flag": "🇬🇷", "is_schengen": true}, {"id": "hungary", "name": "Macaristan", "code": "HU", "flag": "🇭🇺", "is_schengen": true}, {"id": "netherlands", "name": "Hollanda", "code": "NL", "flag": "🇳🇱", "is_schengen": true}, {"id": "norway", "name": "Norveç", "code": "NO", "flag": "🇳🇴", "is_schengen": true}]$countries$::jsonb) as c(id text,name text,code text,flag text,is_schengen boolean) on conflict(id) do nothing;
insert into public.country_documents(id,country_id,title,body,category,source_url,visa_type,sort_order,requirement,source_name,source_document,source_type,source_scope,source_updated_at,source_checked_at,topic_ids)
select id,country_id,title,body,category,source_url,visa_type,sort_order,requirement,source_name,source_document,source_type,source_scope,source_updated_at,source_checked_at,topic_ids from jsonb_to_recordset($documents$[{"id": "9033ad96-043b-505a-aefa-a9cad184bddb", "country_id": "germany", "title": "Pasaport", "body": "Seyahat bitiminden ve Schengen’den planlanan ayrılıştan sonra en az 3 ay geçerli bir pasaport sun. Ülkenin geçerlilik, boş sayfa ve önceki pasaport kopyası koşullarını da kontrol et.", "category": "Turistik vize", "source_url": "https://home-affairs.ec.europa.eu/policies/schengen/visa-policy/applying-schengen-visa_en", "visa_type": "tourism_c", "sort_order": 1, "requirement": "required", "source_name": "Avrupa Komisyonu – Schengen vizesine başvuru", "source_document": "Ortak kısa süreli Schengen çerçevesi", "source_type": "official", "source_scope": "Kısa süreli ziyaretlerde doğru Schengen kategorisini seç. Resmî sayfa, seyahat amacı ile randevu kategorisi uyuşmadığında başvurunun kabul edilmeyebileceğini belirtiyor.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": ["passport"]}, {"id": "fa22f323-2b78-5d7f-89f1-3559f1610e1b", "country_id": "germany", "title": "Başvuru formu", "body": "Eksiksiz doldurulmuş ve şahsen imzalanmış başvuru formu ile İkamet Kanunu’nun 54. maddesine göre gerekli beyannameyi sun.", "category": "Turistik vize", "source_url": "https://tuerkei.diplo.de/tr-tr/service/05-visaeinreise/2768822-2768822", "visa_type": "tourism_c", "sort_order": 2, "requirement": "required", "source_name": "Almanya Türkiye temsilcilikleri – Turistik amaçlı vize kontrol listesi", "source_document": "Türkiye’den turistik Schengen başvurusu", "source_type": "official", "source_scope": "Kısa süreli ziyaretlerde doğru Schengen kategorisini seç. Resmî sayfa, seyahat amacı ile randevu kategorisi uyuşmadığında başvurunun kabul edilmeyebileceğini belirtiyor.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": []}, {"id": "464ea359-b548-5128-ad29-cf7a21adf681", "country_id": "germany", "title": "Biyometrik fotoğraf", "body": "Turistik kontrol listesi 1 biyometrik vesikalık fotoğraf ister. Ölçü ve teknik koşullar için aynı sayfanın Schengen genel bilgiler bağlantısını kullan.", "category": "Turistik vize", "source_url": "https://tuerkei.diplo.de/tr-tr/service/05-visaeinreise/2768822-2768822", "visa_type": "tourism_c", "sort_order": 3, "requirement": "required", "source_name": "Almanya Türkiye temsilcilikleri – Turistik amaçlı vize kontrol listesi", "source_document": "Türkiye’den turistik Schengen başvurusu", "source_type": "official", "source_scope": "Kısa süreli ziyaretlerde doğru Schengen kategorisini seç. Resmî sayfa, seyahat amacı ile randevu kategorisi uyuşmadığında başvurunun kabul edilmeyebileceğini belirtiyor.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": []}, {"id": "84769a85-f78c-5e9b-b9b7-39e3bb3cb10d", "country_id": "germany", "title": "Seyahat sağlık sigortası", "body": "Schengen seyahatinin tamamında geçerli; acil tıbbi bakım, hastane tedavisi ve tıbbi nedenlerle veya vefat halinde ülkeye geri dönüşü kapsayan seyahat sağlık sigortasını sun.", "category": "Turistik vize", "source_url": "https://home-affairs.ec.europa.eu/policies/schengen/visa-policy/applying-schengen-visa_en", "visa_type": "tourism_c", "sort_order": 4, "requirement": "required", "source_name": "Avrupa Komisyonu – Schengen vizesine başvuru", "source_document": "Ortak kısa süreli Schengen çerçevesi", "source_type": "official", "source_scope": "Kısa süreli ziyaretlerde doğru Schengen kategorisini seç. Resmî sayfa, seyahat amacı ile randevu kategorisi uyuşmadığında başvurunun kabul edilmeyebileceğini belirtiyor.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": []}, {"id": "036a9274-9adf-586e-a9e2-4560cc54ed37", "country_id": "germany", "title": "Ulaşım rezervasyonu ve seyahat planı", "body": "Uçuş rezervasyonu, planlanan diğer ulaşım araçlarına ilişkin kanıt veya seyahat güzergâhını sun. Birden fazla ülke varsa aradaki yolculukları ve kalış tarihlerini açıkla.", "category": "Turistik vize", "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "visa_type": "tourism_c", "sort_order": 5, "requirement": "required", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "Kısa süreli ziyaretlerde doğru Schengen kategorisini seç. Resmî sayfa, seyahat amacı ile randevu kategorisi uyuşmadığında başvurunun kabul edilmeyebileceğini belirtiyor.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": []}, {"id": "fedca99c-9002-521b-a481-389ceea9a39e", "country_id": "germany", "title": "Konaklama ve davet mektubu", "body": "Otel rezervasyonu veya seyahatin tamamında nerede kalacağını gösteren başka bir konaklama kanıtı hazırla. Aile/arkadaş yanında kalıyorsan ülkenin o ziyaret türüne ait davet ve ev sahibi belgelerini kullan.", "category": "Turistik vize", "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "visa_type": "tourism_c", "sort_order": 6, "requirement": "required", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "Kısa süreli ziyaretlerde doğru Schengen kategorisini seç. Resmî sayfa, seyahat amacı ile randevu kategorisi uyuşmadığında başvurunun kabul edilmeyebileceğini belirtiyor.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": ["invitation"]}, {"id": "de37dcd7-4466-59a6-b18a-ad74b0a70937", "country_id": "germany", "title": "Maddi durum ve banka hesap dökümleri", "body": "Son 3 aylık banka hesap özetlerini, son 3 aylık maaş bordrolarını ve varsa son 3 aylık emekli maaşı ödemelerini durumuna göre sun. Masrafları karşılayacak yeterli mali kaynağı belgelemelisin.", "category": "Turistik vize", "source_url": "https://tuerkei.diplo.de/tr-tr/service/05-visaeinreise/2768822-2768822", "visa_type": "tourism_c", "sort_order": 7, "requirement": "required", "source_name": "Almanya Türkiye temsilcilikleri – Turistik amaçlı vize kontrol listesi", "source_document": "Türkiye’den turistik Schengen başvurusu", "source_type": "official", "source_scope": "Kısa süreli ziyaretlerde doğru Schengen kategorisini seç. Resmî sayfa, seyahat amacı ile randevu kategorisi uyuşmadığında başvurunun kabul edilmeyebileceğini belirtiyor.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": ["finance", "sponsor"]}, {"id": "6229c32e-5f08-50da-b946-bc0e26c37e0a", "country_id": "germany", "title": "Çalışan, şirket sahibi, emekli veya çiftçi belgeleri", "body": "Durumuna göre: çalışan için işveren/izin yazısı, SGK işe giriş ve okunabilir QR kodlu hizmet dökümü; şirket sahibi için oda/ticaret sicil kaydı, vergi ve faaliyet belgeleri; emekli için emekli maaşı kanıtı; çiftçi için ziraat odası belgesi sun. Hepsi her başvuran için birlikte istenmez.", "category": "Turistik vize", "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "visa_type": "tourism_c", "sort_order": 8, "requirement": "conditional", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "Kısa süreli ziyaretlerde doğru Schengen kategorisini seç. Resmî sayfa, seyahat amacı ile randevu kategorisi uyuşmadığında başvurunun kabul edilmeyebileceğini belirtiyor.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": ["employment"]}, {"id": "02c8bbc6-20ba-57e1-9a7a-493fb3a3e6a1", "country_id": "germany", "title": "Öğrenci belgesi", "body": "Öğrenciysen güncel öğrenci belgeni hazırla. Yükseköğretim için YÖK tarafından düzenlenen, okunabilir QR kodlu öğrenci belgesi; diğer öğrenciler için okul belgesi ortak Türkiye listesinde yer alır.", "category": "Turistik vize", "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "visa_type": "tourism_c", "sort_order": 9, "requirement": "conditional", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "Kısa süreli ziyaretlerde doğru Schengen kategorisini seç. Resmî sayfa, seyahat amacı ile randevu kategorisi uyuşmadığında başvurunun kabul edilmeyebileceğini belirtiyor.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": ["student"]}, {"id": "7292d17a-ead7-5cc6-9248-943f12c03d7c", "country_id": "germany", "title": "Tam tekmil vukuatlı nüfus kayıt örneği", "body": "e-Devlet üzerinden alınmış barkod/QR kodlu Tam Tekmil Vukuatlı Nüfus Kayıt Örneği turistik kontrol listesinde istenir.", "category": "Turistik vize", "source_url": "https://tuerkei.diplo.de/tr-tr/service/05-visaeinreise/2768822-2768822", "visa_type": "tourism_c", "sort_order": 10, "requirement": "required", "source_name": "Almanya Türkiye temsilcilikleri – Turistik amaçlı vize kontrol listesi", "source_document": "Türkiye’den turistik Schengen başvurusu", "source_type": "official", "source_scope": "Kısa süreli ziyaretlerde doğru Schengen kategorisini seç. Resmî sayfa, seyahat amacı ile randevu kategorisi uyuşmadığında başvurunun kabul edilmeyebileceğini belirtiyor.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": []}, {"id": "9b72d5ce-60e1-5782-9361-044267a6b0a8", "country_id": "germany", "title": "Sponsor ve masraf karşılama belgeleri", "body": "Masrafların başka biri tarafından karşılanıyorsa kimin hangi masrafları karşıladığını, finansal kaynakları ve başvuranla bağını belgele. Resmî ülke listesinin istediği sponsor formunu veya taahhüdünü kullan.", "category": "Turistik vize", "source_url": "https://tuerkei.diplo.de/tr-tr/service/05-visaeinreise/1514562-1514562", "visa_type": "tourism_c", "sort_order": 11, "requirement": "conditional", "source_name": "Almanya’nın Türkiye’deki dış temsilcilikleri", "source_document": "Ülkeye özgü başvuru bilgisi", "source_type": "official", "source_scope": "Kısa süreli ziyaretlerde doğru Schengen kategorisini seç. Resmî sayfa, seyahat amacı ile randevu kategorisi uyuşmadığında başvurunun kabul edilmeyebileceğini belirtiyor.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": ["sponsor"]}, {"id": "12865929-3a50-548c-8e06-d9bf74f08589", "country_id": "germany", "title": "18 yaş altı başvuruları", "body": "18 yaşından küçük kişi tek başına, yalnız bir ebeveynle veya yasal vasiyle seyahat ediyorsa seyahat etmeyen ebeveyn/vasinin noter onaylı izni ya da tek velayeti kanıtlayan belge gerekir. Tek velayet ve diğer istisnaları belgelendir.", "category": "Turistik vize", "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "visa_type": "tourism_c", "sort_order": 12, "requirement": "conditional", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "Kısa süreli ziyaretlerde doğru Schengen kategorisini seç. Resmî sayfa, seyahat amacı ile randevu kategorisi uyuşmadığında başvurunun kabul edilmeyebileceğini belirtiyor.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": []}, {"id": "0fb693be-a2ca-588a-972c-ceb993a81309", "country_id": "germany", "title": "Türkiye’de yasal ikamet belgesi", "body": "Türk vatandaşı değilsen, ortak Türkiye listesine göre Schengen’den planlanan ayrılıştan en az 3 ay sonrasına kadar geçerli Türkiye ikamet belgesini sun. Başvuru yetkisini ve vatandaşlığına göre istisnaları resmî temsilcilikten kontrol et.", "category": "Turistik vize", "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "visa_type": "tourism_c", "sort_order": 13, "requirement": "conditional", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "Kısa süreli ziyaretlerde doğru Schengen kategorisini seç. Resmî sayfa, seyahat amacı ile randevu kategorisi uyuşmadığında başvurunun kabul edilmeyebileceğini belirtiyor.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": []}, {"id": "45004d1b-8c25-5f13-9992-6c4bbfdcc223", "country_id": "estonia", "title": "Pasaport", "body": "Seyahat bitiminden ve Schengen’den planlanan ayrılıştan sonra en az 3 ay geçerli bir pasaport sun. Ülkenin geçerlilik, boş sayfa ve önceki pasaport kopyası koşullarını da kontrol et.", "category": "Turistik vize", "source_url": "https://home-affairs.ec.europa.eu/policies/schengen/visa-policy/applying-schengen-visa_en", "visa_type": "tourism_c", "sort_order": 1, "requirement": "required", "source_name": "Avrupa Komisyonu – Schengen vizesine başvuru", "source_document": "Ortak kısa süreli Schengen çerçevesi", "source_type": "official", "source_scope": "Turizm, aile/arkadaş ziyareti ve iş seyahati listeleri ayrı. Bu rehber Türkiye’den yapılan kısa süreli turistik başvuruyu esas alır.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": ["passport"]}, {"id": "79301ff0-98b3-52a2-8f75-74dc71f402a8", "country_id": "estonia", "title": "Başvuru formu", "body": "Büyükelçiliğe doğrudan başvuruda formu çevrimiçi doldur; çıktısını 37. maddede ve sonunda imzala. Form Estonca, İngilizce veya Türkçe doldurulabilir. VFS başvurusunda VFS’nin form talimatını izle.", "category": "Turistik vize", "source_url": "https://ankara.mfa.ee/necessary-documents-to-apply-for-a-schengen-visa/", "visa_type": "tourism_c", "sort_order": 2, "requirement": "required", "source_name": "Estonya Ankara Büyükelçiliği", "source_document": "Ülkeye özgü başvuru bilgisi", "source_type": "official", "source_scope": "Turizm, aile/arkadaş ziyareti ve iş seyahati listeleri ayrı. Bu rehber Türkiye’den yapılan kısa süreli turistik başvuruyu esas alır.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": []}, {"id": "28a9e224-1f92-5d9b-af9e-38247a823e8a", "country_id": "estonia", "title": "Biyometrik fotoğraf", "body": "Son 6 ay içinde çekilmiş, 35 × 45 mm ölçülerinde, açık fonlu 1 renkli fotoğrafı forma yapıştır. Yüz açıkça görünmeli; resmî sayfanın fotoğraf koşullarını takip et.", "category": "Turistik vize", "source_url": "https://ankara.mfa.ee/necessary-documents-to-apply-for-a-schengen-visa/", "visa_type": "tourism_c", "sort_order": 3, "requirement": "required", "source_name": "Estonya Ankara Büyükelçiliği", "source_document": "Ülkeye özgü başvuru bilgisi", "source_type": "official", "source_scope": "Turizm, aile/arkadaş ziyareti ve iş seyahati listeleri ayrı. Bu rehber Türkiye’den yapılan kısa süreli turistik başvuruyu esas alır.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": []}, {"id": "fde7ab67-af1d-55cf-a252-d9048cecb2d5", "country_id": "estonia", "title": "Seyahat sağlık sigortası", "body": "Tüm Schengen ülkelerinde ve planlanan seyahatin tamamında geçerli en az 30.000 € teminatlı sigorta sun. Acil sağlık, hastane ve tıbbi/vefat nedeniyle geri dönüşü kapsamalı. Çok girişli başvuruda kaynak ilk planlanan ziyaret için sigorta ister.", "category": "Turistik vize", "source_url": "https://ankara.mfa.ee/necessary-documents-to-apply-for-a-schengen-visa/", "visa_type": "tourism_c", "sort_order": 4, "requirement": "required", "source_name": "Estonya Ankara Büyükelçiliği", "source_document": "Ülkeye özgü başvuru bilgisi", "source_type": "official", "source_scope": "Turizm, aile/arkadaş ziyareti ve iş seyahati listeleri ayrı. Bu rehber Türkiye’den yapılan kısa süreli turistik başvuruyu esas alır.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": []}, {"id": "e4ae3d91-9951-59cb-a4f1-e323ef6e6742", "country_id": "estonia", "title": "Ulaşım rezervasyonu ve seyahat planı", "body": "Uçuş rezervasyonu, planlanan diğer ulaşım araçlarına ilişkin kanıt veya seyahat güzergâhını sun. Birden fazla ülke varsa aradaki yolculukları ve kalış tarihlerini açıkla.", "category": "Turistik vize", "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "visa_type": "tourism_c", "sort_order": 5, "requirement": "required", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "Turizm, aile/arkadaş ziyareti ve iş seyahati listeleri ayrı. Bu rehber Türkiye’den yapılan kısa süreli turistik başvuruyu esas alır.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": []}, {"id": "95ba1f59-9b5b-56f8-8d3f-4f255ba816d8", "country_id": "estonia", "title": "Konaklama ve davet mektubu", "body": "Otel rezervasyonu veya seyahatin tamamında nerede kalacağını gösteren başka bir konaklama kanıtı hazırla. Aile/arkadaş yanında kalıyorsan ülkenin o ziyaret türüne ait davet ve ev sahibi belgelerini kullan.", "category": "Turistik vize", "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "visa_type": "tourism_c", "sort_order": 6, "requirement": "required", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "Turizm, aile/arkadaş ziyareti ve iş seyahati listeleri ayrı. Bu rehber Türkiye’den yapılan kısa süreli turistik başvuruyu esas alır.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": ["invitation"]}, {"id": "dd553b78-f701-5b1e-a62c-6c1ce387fdf2", "country_id": "estonia", "title": "Maddi durum ve banka hesap dökümleri", "body": "Son 3 aylık hesap hareketlerini gösteren banka dökümü ve düzenli gelir kanıtını hazırla; örneğin son 3 aylık maaş bordroları. Bakiye ve düzenli gelir, seyahat masraflarının nasıl karşılanacağını açıklamalı.", "category": "Turistik vize", "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "visa_type": "tourism_c", "sort_order": 7, "requirement": "required", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "Turizm, aile/arkadaş ziyareti ve iş seyahati listeleri ayrı. Bu rehber Türkiye’den yapılan kısa süreli turistik başvuruyu esas alır.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": ["finance", "sponsor"]}, {"id": "d269f51d-c54a-5df7-ab33-73c0da8e4d81", "country_id": "estonia", "title": "Çalışan, şirket sahibi, emekli veya çiftçi belgeleri", "body": "Durumuna göre: çalışan için işveren/izin yazısı, SGK işe giriş ve okunabilir QR kodlu hizmet dökümü; şirket sahibi için oda/ticaret sicil kaydı, vergi ve faaliyet belgeleri; emekli için emekli maaşı kanıtı; çiftçi için ziraat odası belgesi sun. Hepsi her başvuran için birlikte istenmez.", "category": "Turistik vize", "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "visa_type": "tourism_c", "sort_order": 8, "requirement": "conditional", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "Turizm, aile/arkadaş ziyareti ve iş seyahati listeleri ayrı. Bu rehber Türkiye’den yapılan kısa süreli turistik başvuruyu esas alır.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": ["employment"]}, {"id": "5ece6e99-c174-5cb2-983f-b941a129e622", "country_id": "estonia", "title": "Öğrenci belgesi", "body": "Öğrenciysen güncel öğrenci belgeni hazırla. Yükseköğretim için YÖK tarafından düzenlenen, okunabilir QR kodlu öğrenci belgesi; diğer öğrenciler için okul belgesi ortak Türkiye listesinde yer alır.", "category": "Turistik vize", "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "visa_type": "tourism_c", "sort_order": 9, "requirement": "conditional", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "Turizm, aile/arkadaş ziyareti ve iş seyahati listeleri ayrı. Bu rehber Türkiye’den yapılan kısa süreli turistik başvuruyu esas alır.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": ["student"]}, {"id": "306ce5b4-2d00-570f-9aa1-3a654b8bdda0", "country_id": "estonia", "title": "Tam tekmil vukuatlı nüfus kayıt örneği", "body": "Ortak Türkiye destekleyici belge listesinde tam tekmil vukuatlı nüfus kayıt örneği bulunur. Ülkenin listesinde belirtilen format, tercüme ve aile bağı belgelerini ayrıca kontrol et.", "category": "Turistik vize", "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "visa_type": "tourism_c", "sort_order": 10, "requirement": "required", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "Turizm, aile/arkadaş ziyareti ve iş seyahati listeleri ayrı. Bu rehber Türkiye’den yapılan kısa süreli turistik başvuruyu esas alır.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": []}, {"id": "fbb73f5d-fa55-5468-a71d-c85c1579bfee", "country_id": "estonia", "title": "Sponsor ve masraf karşılama belgeleri", "body": "Masrafların başka biri tarafından karşılanıyorsa kimin hangi masrafları karşıladığını, finansal kaynakları ve başvuranla bağını belgele. Resmî ülke listesinin istediği sponsor formunu veya taahhüdünü kullan.", "category": "Turistik vize", "source_url": "https://ankara.mfa.ee/necessary-documents-to-apply-for-a-schengen-visa/", "visa_type": "tourism_c", "sort_order": 11, "requirement": "conditional", "source_name": "Estonya Ankara Büyükelçiliği", "source_document": "Ülkeye özgü başvuru bilgisi", "source_type": "official", "source_scope": "Turizm, aile/arkadaş ziyareti ve iş seyahati listeleri ayrı. Bu rehber Türkiye’den yapılan kısa süreli turistik başvuruyu esas alır.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": ["sponsor"]}, {"id": "129f453f-cf27-54ef-bdf9-5339c9a18939", "country_id": "estonia", "title": "18 yaş altı başvuruları", "body": "18 yaşından küçük kişi tek başına, yalnız bir ebeveynle veya yasal vasiyle seyahat ediyorsa seyahat etmeyen ebeveyn/vasinin noter onaylı izni ya da tek velayeti kanıtlayan belge gerekir. Tek velayet ve diğer istisnaları belgelendir.", "category": "Turistik vize", "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "visa_type": "tourism_c", "sort_order": 12, "requirement": "conditional", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "Turizm, aile/arkadaş ziyareti ve iş seyahati listeleri ayrı. Bu rehber Türkiye’den yapılan kısa süreli turistik başvuruyu esas alır.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": []}, {"id": "887b2216-e86d-5987-8881-9a52dd1a4227", "country_id": "estonia", "title": "Türkiye’de yasal ikamet belgesi", "body": "Türk vatandaşı değilsen, ortak Türkiye listesine göre Schengen’den planlanan ayrılıştan en az 3 ay sonrasına kadar geçerli Türkiye ikamet belgesini sun. Başvuru yetkisini ve vatandaşlığına göre istisnaları resmî temsilcilikten kontrol et.", "category": "Turistik vize", "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "visa_type": "tourism_c", "sort_order": 13, "requirement": "conditional", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "Turizm, aile/arkadaş ziyareti ve iş seyahati listeleri ayrı. Bu rehber Türkiye’den yapılan kısa süreli turistik başvuruyu esas alır.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": []}, {"id": "2ade7b8d-2198-5041-bcce-1a47c3f5e2c8", "country_id": "poland", "title": "Pasaport", "body": "Son 10 yılda düzenlenmiş, istenen vizenin bitişinden sonra en az 3 ay geçerli ve en az 2 boş vize sayfalı pasaport sun. Fotoğraflı kişisel bilgi sayfası kopyasını ve varsa başka geçerli pasaportunu ekle.", "category": "Turistik vize", "source_url": "https://www.gov.pl/web/turkiye/schengen-vizesi-c-tipi-vize-basvurusunda-bulunmak-istiyorum-1", "visa_type": "tourism_c", "sort_order": 1, "requirement": "required", "source_name": "Polonya Cumhuriyeti Türkiye temsilcilikleri", "source_document": "Ülkeye özgü başvuru bilgisi", "source_type": "official", "source_scope": "90 günü aşmayan seyahat için C tipi Schengen başvurusunu seç; D tipi ulusal vize listesiyle karıştırma.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": ["passport"]}, {"id": "12aba16a-c2d7-5d1c-82da-3d01237e69d5", "country_id": "poland", "title": "Başvuru formu", "body": "e-Konsulat üzerinden çevrimiçi doldurulmuş formun çıktısını al ve imzala. Başvuru merkezi randevusu ayrı bir işlemdir.", "category": "Turistik vize", "source_url": "https://www.gov.pl/web/turkiye/schengen-vizesi-c-tipi-vize-basvurusunda-bulunmak-istiyorum-1", "visa_type": "tourism_c", "sort_order": 2, "requirement": "required", "source_name": "Polonya Cumhuriyeti Türkiye temsilcilikleri", "source_document": "Ülkeye özgü başvuru bilgisi", "source_type": "official", "source_scope": "90 günü aşmayan seyahat için C tipi Schengen başvurusunu seç; D tipi ulusal vize listesiyle karıştırma.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": []}, {"id": "423c4a48-f5a9-56ab-9a94-11279e935553", "country_id": "poland", "title": "Biyometrik fotoğraf", "body": "Son 6 ayda çekilmiş, 35 × 45 mm, beyaz fonlu renkli biyometrik fotoğraf hazırla. Yüz fotoğrafın %70–80’ini kaplamalı; resmî fotoğraf talimatını takip et.", "category": "Turistik vize", "source_url": "https://www.gov.pl/web/turkiye/schengen-vizesi-c-tipi-vize-basvurusunda-bulunmak-istiyorum-1", "visa_type": "tourism_c", "sort_order": 3, "requirement": "required", "source_name": "Polonya Cumhuriyeti Türkiye temsilcilikleri", "source_document": "Ülkeye özgü başvuru bilgisi", "source_type": "official", "source_scope": "90 günü aşmayan seyahat için C tipi Schengen başvurusunu seç; D tipi ulusal vize listesiyle karıştırma.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": []}, {"id": "d26e9747-4545-57fe-9d0e-fac7f783b28c", "country_id": "poland", "title": "Seyahat sağlık sigortası", "body": "Tüm Schengen ülkelerinde geçerli en az 30.000 € teminatlı sigorta sun. Çok girişli vize başvurusunda resmî sayfa ilk seyahatteki kalış süresini kapsayan poliçe ister.", "category": "Turistik vize", "source_url": "https://www.gov.pl/web/turkiye/schengen-vizesi-c-tipi-vize-basvurusunda-bulunmak-istiyorum-1", "visa_type": "tourism_c", "sort_order": 4, "requirement": "required", "source_name": "Polonya Cumhuriyeti Türkiye temsilcilikleri", "source_document": "Ülkeye özgü başvuru bilgisi", "source_type": "official", "source_scope": "90 günü aşmayan seyahat için C tipi Schengen başvurusunu seç; D tipi ulusal vize listesiyle karıştırma.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": []}, {"id": "0bfe9dc0-35a6-5092-aa09-da62749dfa0f", "country_id": "poland", "title": "Ulaşım rezervasyonu ve seyahat planı", "body": "Uçuş rezervasyonu, planlanan diğer ulaşım araçlarına ilişkin kanıt veya seyahat güzergâhını sun. Birden fazla ülke varsa aradaki yolculukları ve kalış tarihlerini açıkla.", "category": "Turistik vize", "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "visa_type": "tourism_c", "sort_order": 5, "requirement": "required", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "90 günü aşmayan seyahat için C tipi Schengen başvurusunu seç; D tipi ulusal vize listesiyle karıştırma.", "source_updated_at": null, "source_checked_at": "2026-10-22", "topic_ids": []}, {"id": "7da3175b-cf1d-5d59-bd84-59e22ed541c5", "country_id": "poland", "title": "Konaklama ve davet mektubu", "body": "Otel rezervasyonu veya seyahatin tamamında nerede kalacağını gösteren başka bir konaklama kanıtı hazırla. Aile/arkadaş yanında kalıyorsan ülkenin o ziyaret türüne ait davet ve ev sahibi belgelerini kullan.", "category": "Turistik vize", "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "visa_type": "tourism_c", "sort_order": 6, "requirement": "required", "source_name": "Avrup